-- L'escale Créole : descriptifs « recette » (ingrédients + grandes étapes + secret du chef) — 2026-10-08.
-- Textes validés par le porteur du projet, rédigés d'après des recettes réunionnaises / malgaches
-- de référence ; « le secret du chef » couvre ce qui varie d'une cuisine à l'autre. FR + EN + IT.
-- (Le rougail saucisses a sa propre migration, escale_creole_descriptif_rougail.)

create temp table _desc (nom text, fr text, en text, it text) on commit drop;

update public.products p set description = d.fr
  from _desc d
 where p.restaurant_id = '128e68ab-8e64-4f48-bf79-acc67f3deca9' and not p.is_archived and p.name = d.nom;

select fr, 'en', en, 'manuel' from _desc
union all
select fr, 'it', it, 'manuel' from _desc
on conflict (fr, langue) do nothing;
